<span class="pd-code-line" data-line="15">        <span>return</span> <span>this</span>.<span>text</span>.<span>find</span>($Chapter).<span>filter</span>(<span><span>chapter</span> =&gt;</span> chapter.<span>is</span>($Synopsis) &amp;&amp; chapter !== <span>this</span>.<span>synopsis</span>);</span>
